#include <iostream>
using namespace std;

long long factorialRecursive(int n) {
    if (n <= 1) return 1;
    return n * factorialRecursive(n - 1);
}

long long factorialIterative(int n) {
    long long result = 1;
    for (int i = 2; i <= n; i++) {
        result *= i;
    }
    return result;
}

int main() {
    int numbers[] = {5, 6, 7, 8};

    cout << "阶乘计算结果:" << endl;
    for (int i = 0; i < 4; i++) {
        cout << numbers[i] << "! = " << factorialRecursive(numbers[i]) << endl;
    }

    int n = 10;
    cout << "
递归方法: " << n << "! = " << factorialRecursive(n) << endl;
    cout << "迭代方法: " << n << "! = " << factorialIterative(n) << endl;

    return 0;
}
